390	// TestBatchReturnedReportsFreezeAcrossLaterBatches verifies that after a later
391	// legal batch adjusts the current graph, the earlier preview and apply reports
392	// still describe the relationships at the moment each returned, and a report
393	// the caller never edited re-emits as byte-identical JSON.
394	func TestBatchReturnedReportsFreezeAcrossLaterBatches(t *testing.T) {
395		graph := independenceGraph(t)
396	
397		preview, err := PreviewBatch(graph, replacementPlan())
398		if err != nil {
399			t.Fatalf("first PreviewBatch unexpected error: %v", err)
400		}
401		applied, err := ApplyBatch(graph, replacementPlan())
402		if err != nil {
403			t.Fatalf("first ApplyBatch unexpected error: %v", err)
404		}
405		previewJSON := mustMarshalReport(t, preview)
406		appliedJSON := mustMarshalReport(t, applied)
407	
408		// A second, legal replacement through the existing API: C switches from B
409		// to D. This removes the B->C downstream relationship from the current
410		// graph entirely.
411		second := planOf(change("C", "D"))
412		if _, err := ApplyBatch(graph, second); err != nil {
413			t.Fatalf("second ApplyBatch unexpected error: %v", err)
414		}
415		if got := graph["C"].Parents; !reflect.DeepEqual(got, []string{"D"}) {
416			t.Fatalf("C.Parents = %v, want [D] after the second batch", got)
417		}
418		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D", "E"}) {
419			t.Fatalf("B.Parents = %v, want [D E]", got)
420		}
421		if got := graph["B"].Children; len(got) != 0 {
422			t.Fatalf("B.Children = %v, want empty after C was repointed", got)
423		}
424		if got := graph["D"].Children; !reflect.DeepEqual(got, []string{"B", "C"}) {
425			t.Fatalf("D.Children = %v, want [B C]", got)
426		}
427	
428		// Both earlier reports still describe their return-time graph: C depended
429		// on B then, B already depended on D and E.
430		for name, r := range map[string]*BatchReport{"preview": preview, "apply": applied} {
431			if got := mustReportDataset(t, r, "B").Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
432				t.Errorf("%s report B.upstreams = %v, want frozen [D E]", name, got)
433			}
434			if got := mustReportDataset(t, r, "C").Upstreams; !reflect.DeepEqual(got, []string{"B"}) {
435				t.Errorf("%s report C.upstreams = %v, want frozen [B]", name, got)
436			}
437		}
438		if got := mustMarshalReport(t, preview); got != previewJSON {
439			t.Errorf("preview report JSON drifted after a later batch:\n got %s\nwant %s", got, previewJSON)
440		}
441		if got := mustMarshalReport(t, applied); got != appliedJSON {
442			t.Errorf("apply report JSON drifted after a later batch:\n got %s\nwant %s", got, appliedJSON)
443		}
444	}
445	
446	// TestBatchSharedUpstreamRecordsAreIndependentInReport verifies that when two
447	// datasets end up with the same direct-upstream list, each report record owns
448	// that list: editing one dataset's displayed upstreams must not drag the
449	// other dataset's record along, in either the report or the applied graph.
450	func TestBatchSharedUpstreamRecordsAreIndependentInReport(t *testing.T) {
451		// Roots A, D, E; both B and F currently depend on A; C depends on B.
452		graph := buildGraph(t, P("A"), P("D"), P("E"), P("B", "A"), P("F", "A"), P("C", "B"))
453		plan := planOf(
454			change("B", "E", "D", "D", "E"), // normalizes to [D E]
455			change("F", "D", "E"),           // same final upstreams
456		)
457	
458		report, err := PreviewBatch(graph, plan)
459		if err != nil {
460			t.Fatalf("PreviewBatch unexpected error: %v", err)
461		}
462		iB := datasetIndex(report, "B")
463		iF := datasetIndex(report, "F")
464		if iB < 0 || iF < 0 {
465			t.Fatalf("report missing records: B=%d F=%d", iB, iF)
466		}
467		if got := report.FinalGraph.Datasets[iB].Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
468			t.Fatalf("report B.upstreams = %v, want [D E]", got)
469		}
470		if got := report.FinalGraph.Datasets[iF].Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
471			t.Fatalf("report F.upstreams = %v, want [D E]", got)
472		}
473	
474		// Edit only B's displayed list, in place and via append.
475		report.FinalGraph.Datasets[iB].Upstreams[0] = "X"
476		report.FinalGraph.Datasets[iB].Upstreams = append(report.FinalGraph.Datasets[iB].Upstreams, "Y")
477	
478		if got := report.FinalGraph.Datasets[iF].Upstreams; !reflect.DeepEqual(got, []string{"D", "E"}) {
479			t.Errorf("F.upstreams = %v, want untouched [D E] after editing B's record", got)
480		}
481		if got := mustReportDataset(t, report, "C").Upstreams; !reflect.DeepEqual(got, []string{"B"}) {
482			t.Errorf("C.upstreams = %v, want untouched [B]", got)
483		}
484	
485		// Applying the still-verbatim plan commits independent lists to the graph
486		// as well: F must not have inherited B's display edits.
487		if _, err := ApplyBatch(graph, plan); err != nil {
488			t.Fatalf("ApplyBatch unexpected error: %v", err)
489		}
490		if got := graph["B"].Parents; !reflect.DeepEqual(got, []string{"D", "E"}) {
491			t.Errorf("graph B.Parents = %v, want [D E]", got)
492		}
493		if got := graph["F"].Parents; !reflect.DeepEqual(got, []string{"D", "E"}) {
494			t.Errorf("graph F.Parents = %v, want [D E] (must not follow B's report edit)", got)
495		}
496		if got := graph["D"].Children; !reflect.DeepEqual(got, []string{"B", "F"}) {
497			t.Errorf("D.Children = %v, want [B F]", got)
498		}
499		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
500			t.Errorf("B.Children = %v, want [C]", got)
501		}
502	}
503	
504	// TestBatchEmptyUpstreamsMakesRootWhileOldReportKeepsUpstreams verifies the
505	// root boundary: replacing a dataset's upstreams with an empty list makes it a
506	// root in both the current graph and this batch's report (emitted as []),
507	// while a report returned earlier still carries the non-empty list.
508	func TestBatchEmptyUpstreamsMakesRootWhileOldReportKeepsUpstreams(t *testing.T) {
509		graph := buildGraph(t, P("A"), P("D"), P("B", "A"), P("C", "B"))
510	
511		oldPlan := planOf(change("B", "D"))
512		old, err := PreviewBatch(graph, oldPlan)
513		if err != nil {
514			t.Fatalf("old PreviewBatch unexpected error: %v", err)
515		}
516		if got := mustReportDataset(t, old, "B").Upstreams; !reflect.DeepEqual(got, []string{"D"}) {
517			t.Fatalf("old report B.upstreams = %v, want [D]", got)
518		}
519		oldJSON := mustMarshalReport(t, old)
520	
521		// Now clear B's upstreams through the same API. B becomes a root but keeps
522		// its downstream C.
523		emptyPlan := planOf(change("B"))
524		report, err := ApplyBatch(graph, emptyPlan)
525		if err != nil {
526			t.Fatalf("ApplyBatch empty-upstreams unexpected error: %v", err)
527		}
528		if got := graph["B"].Parents; len(got) != 0 {
529			t.Errorf("B.Parents = %v, want empty (root)", got)
530		}
531		if got := graph["B"].Children; !reflect.DeepEqual(got, []string{"C"}) {
532			t.Errorf("B.Children = %v, want [C] (downstream kept when becoming a root)", got)
533		}
534		if got := graph["A"].Children; len(got) != 0 {
535			t.Errorf("A.Children = %v, want empty", got)
536		}
537		if roots := Roots(graph); !reflect.DeepEqual(roots, []string{"A", "B", "D"}) {
538			t.Errorf("Roots = %v, want [A B D]", roots)
539		}
540	
541		// The new report shows B as a root with a non-nil empty list (JSON []).
542		got := mustReportDataset(t, report, "B").Upstreams
543		if got == nil || len(got) != 0 {
544			t.Errorf("new report B.upstreams = %v, want non-nil empty list", got)
545		}
546		if b := mustMarshalReport(t, report); !containsEmptyUpstreamsFor(b, "B") {
547			t.Errorf("new report JSON does not show B with \"upstreams\":[]:\n%s", b)
548		}
549		if got := mustReportDataset(t, report, "C").Upstreams; !reflect.DeepEqual(got, []string{"B"}) {
550			t.Errorf("new report C.upstreams = %v, want [B]", got)
551		}
552	
553		// The earlier report is frozen on the non-empty upstream, byte for byte.
554		if got := mustReportDataset(t, old, "B").Upstreams; !reflect.DeepEqual(got, []string{"D"}) {
555			t.Errorf("old report B.upstreams = %v, want frozen [D]", got)
556		}
557		if got := mustMarshalReport(t, old); got != oldJSON {
558			t.Errorf("old report JSON drifted after B became a root:\n got %s\nwant %s", got, oldJSON)
559		}
560	}
561	
562	// containsEmptyUpstreamsFor reports whether the report JSON renders name with
563	// an empty upstreams list (struct field order is name then upstreams).
564	func containsEmptyUpstreamsFor(reportJSON, name string) bool {
565		quoted, err := json.Marshal(name)
566		if err != nil {
567			return false
568		}
569		return strings.Contains(reportJSON, `"name":`+string(quoted)+`,"upstreams":[]`)
570	}
