11	// TestReadersShareGraphStructureRules is a parity guard for the consolidation:
12	// the standalone graph file reader and the snapshot graph reader must agree on
13	// every graph's validity, on the sentinel error category when invalid, and on
14	// the normalized graph when valid.
15	func TestReadersShareGraphStructureRules(t *testing.T) {
16		graphs := map[string]string{
17			"empty":                 `{"datasets":[]}`,
18			"single root":           `{"datasets":[{"name":"A","upstreams":[]}]}`,
19			"chain shuffled":        `{"datasets":[{"name":"C","upstreams":["B","A","B"]},{"name":"A","upstreams":[]},{"name":"B","upstreams":["A"]}]}`,
20			"case and spaces":       `{"datasets":[{"name":" A ","upstreams":[]},{"name":"a","upstreams":[" A "]}]}`,
21			"empty name":            `{"datasets":[{"name":"","upstreams":[]}]}`,
22			"duplicate dataset":     `{"datasets":[{"name":"A","upstreams":[]},{"name":"A","upstreams":[]}]}`,
23			"missing upstream":      `{"datasets":[{"name":"A","upstreams":["ghost"]}]}`,
24			"direct self cycle":     `{"datasets":[{"name":"A","upstreams":["A"]}]}`,
25			"indirect cycle":        `{"datasets":[{"name":"A","upstreams":["B"]},{"name":"B","upstreams":["A"]}]}`,
26			"empty upstream string": `{"datasets":[{"name":"A","upstreams":[""]}]}`,
27			"datasets field twice":  `{"datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
28			"name field twice":      `{"datasets":[{"name":"A","name":"A","upstreams":[]}]}`,
29			"upstreams field twice": `{"datasets":[{"name":"A","upstreams":[],"upstreams":[]}]}`,
30		}
31	
32		category := func(err error) string {
33			switch {
34			case err == nil:
35				return ""
36			case errors.Is(err, ErrInvalidArgument):
37				return "invalid"
38			case errors.Is(err, ErrNotFound):
39				return "notfound"
40			case errors.Is(err, ErrCycle):
41				return "cycle"
42			default:
43				return "other"
44			}
45		}
46	
47		for name, data := range graphs {
48			t.Run(name, func(t *testing.T) {
49				fileGraph, fileErr := UnmarshalGraphFile([]byte(data))
50	
51				// For a valid graph, marshal a correctly-addressed snapshot so the
52				// snapshot-only content-id rule passes and only the shared graph
53				// rules are exercised. For an invalid graph the structure is
54				// rejected before content-id integrity, so a dummy id suffices.
55				var snapDoc []byte
56				if fileErr == nil {
57					b, err := MarshalSnapshot(snapshotOf(t, data))
58					if err != nil {
59						t.Fatalf("marshal snapshot: %v", err)
60					}
61					snapDoc = b
62				} else {
63					snapDoc = []byte(`{"formatVersion":1,"contentId":"sha256:deadbeef","graph":` + data + `}`)
64				}
65				snap, snapErr := ParseSnapshot(snapDoc)
66	
67				if category(fileErr) != category(snapErr) {
68					t.Fatalf("category mismatch: file=%v snapshot=%v", fileErr, snapErr)
69				}
70				if fileErr != nil {
71					return
72				}
73	
74				// Valid graph: both readers keep the same normalized graph.
75				fileAdj, err := graphAdjacency(fileGraph)
76				if err != nil {
77					t.Fatalf("graphAdjacency: %v", err)
78				}
79				fileBytes, err := json.Marshal(GraphFile{Datasets: adjacencyToDatasets(fileAdj)})
80				if err != nil {
81					t.Fatalf("marshal file graph: %v", err)
82				}
83				snapAdj := adjacencyFromValidFile(snap.Graph)
84				snapBytes, err := json.Marshal(GraphFile{Datasets: adjacencyToDatasets(snapAdj)})
85				if err != nil {
86					t.Fatalf("marshal snapshot graph: %v", err)
87				}
88				if !reflect.DeepEqual(fileBytes, snapBytes) {
89					t.Fatalf("normalized graph differs:\n file %s\n snap %s", fileBytes, snapBytes)
90				}
91			})
92		}
93	}
