95	// TestUnmarshalGraphFileRejectsDuplicateFields: a known field declared twice
96	// within the same object makes the whole graph file ambiguous and must be
97	// rejected, even when the duplicates carry identical values, the first is
98	// null, or the surviving value alone would form a legal graph. Field names
99	// are recognized after JSON unescaping and with the decoder's Unicode case
100	// folding, so escaped or fold-equivalent spellings of a second declaration
101	// still collide.
102	func TestUnmarshalGraphFileRejectsDuplicateFields(t *testing.T) {
103		const (
104			longS       = "ſ" // U+017F LATIN SMALL LETTER LONG S, folds to ASCII "s"
105			longSEscape = "\\" + "u017f"
106		)
107	
108		cases := map[string]struct {
109			data     string
110			field    string
111			location string
112		}{
113			"datasets twice identical": {
114				`{"datasets":[{"name":"A","upstreams":[]}],"datasets":[{"name":"A","upstreams":[]}]}`,
115				"datasets", "top level",
116			},
117			"real datasets then empty replacement": {
118				`{"datasets":[{"name":"A","upstreams":[]}],"datasets":[]}`,
119				"datasets", "top level",
120			},
121			"null datasets then real": {
122				`{"datasets":null,"datasets":[{"name":"A","upstreams":[]}]}`,
123				"datasets", "top level",
124			},
125			"name twice same value": {
126				`{"datasets":[{"name":"A","name":"A","upstreams":[]}]}`,
127				"name", `index 0 of "datasets"`,
128			},
129			"null name then valid": {
130				`{"datasets":[{"name":null,"name":"A","upstreams":[]}]}`,
131				"name", `index 0 of "datasets"`,
132			},
133			"upstreams then empty would look like root": {
134				`{"datasets":[{"name":"B","upstreams":["A"],"upstreams":[]},{"name":"A","upstreams":[]}]}`,
135				"upstreams", `index 0 of "datasets"`,
136			},
137			"null upstreams then valid": {
138				`{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":null,"upstreams":["A"]}]}`,
139				"upstreams", `index 1 of "datasets"`,
140			},
141			"escaped name key": {
142				`{"datasets":[{"na\u006de":"A","name":"A","upstreams":[]}]}`,
143				"name", `index 0 of "datasets"`,
144			},
145			"case variant name": {
146				`{"datasets":[{"Name":"A","name":"A","upstreams":[]}]}`,
147				"name", `index 0 of "datasets"`,
148			},
149			"case variant datasets": {
150				`{"Datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
151				"datasets", "top level",
152			},
153			"case variant upstreams": {
154				`{"datasets":[{"name":"A","UPSTREAMS":[],"upstreams":[]}]}`,
155				"upstreams", `index 0 of "datasets"`,
156			},
157			"long s datasets": {
158				`{"data` + longS + `ets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
159				"datasets", "top level",
160			},
161			"long s upstreams via JSON escape": {
162				`{"datasets":[{"name":"A","up` + longSEscape + `treams":[],"upstreams":[]}]}`,
163				"upstreams", `index 0 of "datasets"`,
164			},
165			"big number in unknown field before duplicated datasets": {
166				`{"note":1e400,"datasets":[],"datasets":[{"name":"A","upstreams":[]}]}`,
167				"datasets", "top level",
168			},
169			"big number nested in record before duplicated upstreams": {
170				`{"datasets":[{"name":"A","vals":{"deep":[1e999]},"upstreams":[],"upstreams":[]}]}`,
171				"upstreams", `index 0 of "datasets"`,
172			},
173		}
174		for name, tc := range cases {
175			t.Run(name, func(t *testing.T) {
176				// Every "escape" case really must carry ASCII escape bytes.
177				if strings.Contains(name, "escape") && !strings.Contains(tc.data, longSEscape) && !strings.Contains(tc.data, `\u006d`) {
178					t.Fatalf("test case %q does not actually use a JSON escape", name)
179				}
180				_, err := UnmarshalGraphFile([]byte(tc.data))
181				if !errors.Is(err, ErrInvalidArgument) {
182					t.Fatalf("err = %v, want ErrInvalidArgument", err)
183				}
184				if !strings.Contains(err.Error(), `"`+tc.field+`"`) {
185					t.Errorf("err = %q, want it to name duplicated field %q", err, tc.field)
186				}
187				if !strings.Contains(err.Error(), tc.location) {
188					t.Errorf("err = %q, want it to locate the duplicate %q", err, tc.location)
189				}
190			})
191		}
192	}
193	
194	// TestUnmarshalGraphFileDuplicateTolerances: repetitions that do NOT create
195	// ambiguity stay legal — unknown fields may repeat anywhere (even holding
196	// duplicate keys or oversized numbers inside), each dataset record declares
197	// its own name, and duplicate names inside one upstreams array still count as
198	// one relationship. A known field written once in a case-variant or
199	// fold-equivalent spelling is still recognized.
200	func TestUnmarshalGraphFileDuplicateTolerances(t *testing.T) {
201		cases := map[string]string{
202			"empty graph":                     `{"datasets":[]}`,
203			"unknown top-level field repeats": `{"meta":"x","meta":"y","datasets":[{"name":"A","upstreams":[]}]}`,
204			"unknown record field repeats":    `{"datasets":[{"name":"A","note":1,"note":2,"upstreams":[]}]}`,
205			"known keys nested inside unknown field": `{"meta":{"name":"A","name":"B","datasets":[],"upstreams":null},` +
206				`"datasets":[{"name":"A","upstreams":[]}]}`,
207			"big numbers in unknown fields":          `{"note":1e400,"datasets":[{"name":"A","upstreams":[],"extra":[1e999,{"z":-1e400}]}]}`,
208			"case variant spellings declared once":   `{"Datasets":[{"Name":"A","Upstreams":[]},{"NAME":"B","UPSTREAMS":["A"]}]}`,
209			"duplicate names inside upstreams array": `{"datasets":[{"name":"A","upstreams":[]},{"name":"B","upstreams":["A","A"]}]}`,
210		}
211		for name, data := range cases {
212			t.Run(name, func(t *testing.T) {
213				graph, err := UnmarshalGraphFile([]byte(data))
214				if err != nil {
215					t.Fatalf("UnmarshalGraphFile rejected a legal document: %v", err)
216				}
217				if name == "duplicate names inside upstreams array" {
218					if got := graph["B"].Parents; len(got) != 1 || got[0] != "A" {
219						t.Errorf("B.Parents = %v, want [A] (duplicates count once)", got)
220					}
221				}
222			})
223		}
224	
225		// Dataset names stay case-sensitive and keep their spaces; only field
226		// names fold.
227		graph, err := UnmarshalGraphFile([]byte(`{"datasets":[{"name":" A ","upstreams":[]},{"name":"a","upstreams":[" A "]}]}`))
228		if err != nil {
229			t.Fatalf("case/space-sensitive dataset names rejected: %v", err)
230		}
231		if got := graph["a"].Parents; len(got) != 1 || got[0] != " A " {
232			t.Errorf(`graph["a"].Parents = %v, want [" A "]`, got)
233		}
234	}
